<?php

/**
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class DatPlanconteo extends BaseDatPlanconteo
{

    public function setUp()
    {
        $this->hasMany('DatPlanconteom', array('local' => 'idplan', 'foreign' => 'idplan'));
    }

    /**
     * @param $datos array que contiene los valores a filtrar
     *
     * @return arreglo de planes
     */
    public function obtenerPlanesConteo($datos)
    {
        $filtro = '';
        $arrFiltro = array();
		
		if(is_array($datos['idestructuraop']))
			$arrFiltro[] = " dpc.idestructuraop IN (". implode(',',$datos['idestructuraop']) .") ";
		else
			$arrFiltro[] = " dpc.idestructuraop = '".$datos['idestructuraop']."' ";
		if (isset($datos['criterio'])) {
            $sql = "select idejercicio from mod_datosmaestros.dat_ejerciciocontable where nombre like '{$datos['criterio']}'";
            $filtrado = Doctrine_Manager::connection()->execute($sql)->fetchAll(
                PDO::FETCH_COLUMN
            );
            if (count($filtrado) == 0) {
                $filtrado =  array(-1);
            }
            $arrFiltro[] = " dpc.idejercicio in (".implode(',', $filtrado).") ";
        } else {
            $arrFiltro[] = " dpc.idejercicio = '".$datos['idejerciciosubsistema']."' ";
        }



        if ($datos['estado']) {
            $arrFiltro[] = " dpcm.estado = '".$datos['estado']."' ";
        }
        if (count($arrFiltro) > 0) {
            $filtro = implode(' AND ', $arrFiltro);
        }
        $orderby = ($datos['orderby'] == 'anno') ? 'dpc.idejercicio' : 'dpcm.idperiodo';
        $query = Doctrine_Query::create();
        return $query->select(
        'dpc.idestructuraop as idestructuraop, '
        .'dpc.idejercicio as idejercicio, dpcm.estado as estadoplan, '
        .'dpc.idplan as idplan, dpc.idusuario as idusuario, '
        .'dpcm.idperiodo, dpcm.porciento, '
        .'dpcm.estado, dpcm.idusuarioaprobado')
        ->from('DatPlanconteom dpcm')
        ->innerJoin('dpcm.DatPlanconteo dpc')
        ->where($filtro)
        ->orderby($orderby)
        ->fetchArray();
    }

    public function obtenerPlanesConteoEliminar($idestructuraop)
    {
        $query = Doctrine_Query::create();
        return $query->select('dpc.idejercicio')//,cfg.denom'
                ->from('DatPlanconteo dpc')
                ->where('dpc.idestructuraop = ?', $idestructuraop)
                ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)
                ->execute();
    }

    public function obtenerPlanDadoIdplan($idplan)
    {
        $query = new Doctrine_Query();
        $result = $query->select('idejercicio,estado')
            ->from('DatPlanconteo')
            ->where('idplan=?', $idplan)
            ->execute();
        $arr = $result->toArray();
        return $arr;
    }

    public function obtenerIdPlanDadoAnno($idEjercicioactual, $idestructuraop)
    {
        try {
            $query = new Doctrine_Query();
            $result = $query->select('idplan')
                ->from('DatPlanconteo')
                ->where(" idejercicio= ? and idestructuraop= ?", array($idEjercicioactual, $idestructuraop))
                //->where('ano=?',$anno,'idestructuraop=?',$idestructuraop)
                ->execute();
            $arr = $result->toArray();
            return (is_array($arr) ? $arr[0]['idplan'] : false);
        } catch (Doctrine_Exception $e) {
            echo $e;
        }
    }

    /**
     * @param $idplan criterio para eliminar
     *
     * @return mixed
     */
    public function eliminarPlanConteo($idplan)
    {
        $query = Doctrine_Query::create();
        return $query->delete()
                ->from('DatPlanconteo')
                ->where('idplan=?', $idplan)
                ->execute();
    }

    public function verificarExistePlanAnual($idjercicio, $idestructuraop)
    {
        $query = Doctrine_Query::create();
        return $query->from('DatPlanconteo dpc')
                ->where('dpc.idejercicio=? and dpc.idestructuraop=?', array($idjercicio, $idestructuraop))
                ->count();
    }

    public function verificarExistePlanAnualYNoDic($idejercicio, $idperiodo)
    {
        $query = Doctrine_Query::create();
        return $query->select('dpc.*,dpcm.*')//,cfg.denom'
                ->from('DatPlanconteo dpc')
                ->innerJoin('dpc.DatPlanconteom dpcm')
                ->where('dpc.idejercicio =? AND dpcm.idperiodo =? AND dpcm.estado = 5', array($idejercicio, $idperiodo))
                //->orderby ('dpc.ano ASC')
                ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)
                ->execute();
    }

    /*
     * Se Esta utilizando en hoja de inventario
     * */

    public function verificarExistenciaPlanAnual($idejercicio)
    {
        $query = Doctrine_Query::create();
        return $query->select('dpc.*,dpcm.*')//,cfg.denom'
                ->from('DatPlanconteo dpc')
                ->innerJoin('dpc.DatPlanconteom dpcm')
                ->where('dpc.idejercicio =? AND dpcm.estado = 5', array($idejercicio))
                //->orderby ('dpc.ano ASC')
                ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)
                ->execute();
    }

    public function verificarExistePlanAnualYNoEnero($anno, $iddeposito)
    {
        $query = Doctrine_Query::create();
        return $query->select('dpc.*,dpcm.*')//,cfg.denom'
                ->from('DatPlanconteo dpc')
                ->innerJoin('dpc.DatPlanconteom dpcm')
                ->where(
                    'dpc.ano =? AND dpcm.mes = 1 AND dpcm.estado = 5 AND dpc.idestructuraop =?',
                    array($anno, $iddeposito)
                )
                //->orderby ('dpc.ano ASC')
                ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)
                ->execute();
    }

    public function verificarExistePlanAnualMensual($anno, $idestructuraop, $idmes = '')
    {
        $query = Doctrine_Query::create();
        $filtro = '';
        if ($idmes) {
            $filtro = "AND dpcm.idperiodo = '$idmes'";
        }

        return $query->select('dpc.idplan,dpcm.idplanconteom,dpcm.idperiodo,dpcm.estado,dpcm.porciento')//,cfg.denom'
                ->from('DatPlanconteo dpc')
                ->innerJoin('dpc.DatPlanconteom dpcm')
                ->where("dpc.idejercicio =? AND dpc.idestructuraop =? $filtro", array($anno, $idestructuraop))
                //->orderby ('dpc.ano ASC')
                ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)
                ->execute();
    }

    /*     * *
     * @param $idplan  para identificar el plan a modificar
     * @param $estado  nuevo valor a actualizar
     *
     * @return mixed
     */

    public function actualizaEstadoPlan($idplan, $estado)
    {
        $query = Doctrine_Query::create();
        return $query->update('DatPlanconteo dpc')
                ->set('estado', $estado)
                ->where("dpc.idplan =?", array($idplan))
                ->execute();
    }

}
